  });
});

test("ValidateModelSelection rejects unknown and unavailable models", async () =>
{
  await WithFakeRepoAsync(async (repoRoot) =>
  {
    const config = BuildTestConfig(repoRoot, {
      localInferenceUrl: "http://studio.local:8000/v1/",
